package com.turboio.androidtests;
import android.app.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
/** Runs only the synthetic archive filesystem suite in the target process's isolated synthetic cache folder.
 * Does not open the target's audio, configuration or official databases. */
public final class LifelogAudioArchiveProbe extends Instrumentation {
 private String nonce;
 @Override public void onCreate(Bundle args){super.onCreate(args);nonce=args.getString("probe_id","");start();}
 @Override public void onStart(){Bundle result=new Bundle();Path isolated=null;boolean passed=false;try{
  if(!nonce.matches("[a-f0-9]{32}"))throw new IllegalStateException("ARCHIVE_PROBE_NONCE");File cache=getTargetContext().getCacheDir().getCanonicalFile();isolated=new File(cache,"archive-probe-"+nonce).toPath();Files.createDirectory(isolated);
  Class<?> suite=getClass().getClassLoader().loadClass("com.turboio.androidtests.voice.LifelogAudioArchiveTest");suite.getMethod("main",String[].class).invoke(null,(Object)new String[]{isolated.toString()});Field checks=suite.getDeclaredField("checks");checks.setAccessible(true);result.putInt("checks",checks.getInt(null));Path managerRoot=isolated.resolve("manager-tests");Files.createDirectory(managerRoot);Class<?> manager=getClass().getClassLoader().loadClass("com.turboio.androidtests.voice.LifelogAudioManagerTest");manager.getMethod("main",String[].class).invoke(null,(Object)new String[]{managerRoot.toString()});Field managerChecks=manager.getDeclaredField("checks");managerChecks.setAccessible(true);result.putInt("manager_checks",managerChecks.getInt(null));Path collectorRoot=isolated.resolve("collector-tests");Files.createDirectory(collectorRoot);Class<?> collector=getClass().getClassLoader().loadClass("com.turboio.androidtests.voice.LifelogAudioCollectorTest");collector.getMethod("main",String[].class).invoke(null,(Object)new String[]{collectorRoot.toString()});Field collectorChecks=collector.getDeclaredField("checks");collectorChecks.setAccessible(true);result.putInt("collector_checks",collectorChecks.getInt(null));passed=true;
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();String message=e.getMessage();for(StackTraceElement frame:e.getStackTrace())if(frame.getClassName().startsWith("com.turboio.")){result.putString("failure_location",frame.getClassName()+":"+frame.getLineNumber());break;}result.putString("error",message!=null&&message.matches("[A-Z_]{3,90}")?message:e.getClass().getSimpleName());}
 finally{boolean cleaned=isolated==null;try{if(isolated!=null){try(java.util.stream.Stream<Path> files=Files.walk(isolated)){Iterator<Path> paths=files.sorted(Comparator.reverseOrder()).iterator();while(paths.hasNext())Files.delete(paths.next());}cleaned=!Files.exists(isolated);}}catch(Exception error){cleaned=false;}result.putBoolean("passed",passed&&cleaned);result.putBoolean("synthetic_fixture_removed",cleaned);result.putBoolean("synthetic_only",true);result.putBoolean("target_audio_read_or_capture",false);result.putBoolean("server_or_source_association_verified",false);result.putString("probe_id",nonce);finish(passed&&cleaned?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
 }
}
